import java.util.*;
import java.io.*;

public class Main {
    static final int N = 15;
    static final int M = 100005;
    static final int INF = 1000000000;
    static final int[] move_x = {0, 0, -1, 1};
    static final int[] move_y = {1, -1, 0, 0};
    static char[][] maze = new char[N][N];
    static char[][] S = new char[N][N];
    static int n, t, total;
    static int start_x, start_y, s, e, k1 = 1;
    static int[][] id = new int[N][N];
    static int[][] dist = new int[N][N];
    static int[][] visited = new int[N][N];
    static int[][] Dis = new int[N][N];
    static int[] q = new int[M];
    static Point[] Q = new Point[M];
    static Edge[] edges = new Edge[M];
    static int[] head = new int[N * N * 2];
    static int[] tail = new int[N * N * 2];

    static class Edge {
        int to, prev, flow;
        Edge(int to, int prev, int flow) {
            this.to = to;
            this.prev = prev;
            this.flow = flow;
        }
    }

    static class Point {
        int x, y;
        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    static int edgeCount = 1;

    static boolean check_cell(int x, int y) {
        if (x < 0 || y < 0 || x >= n || y >= n || visited[x][y] != 0 || maze[x][y] < '0' || maze[x][y] > '9') return false;
        return true;
    }

    static boolean bfs() {
        for (int i = 0; i < dist.length; i++) {
            Arrays.fill(dist[i], -1);
        }
        int l = 0, r = 0;
        dist[s / 2][s % 2] = 0;
        q[++r] = s;
        while (l <= r) {
            int p = q[l++];
            for (int i = head[p]; i != 0; i = edges[i].prev) {
                if (edges[i].flow > 0) {
                    int to = edges[i].to;
                    int x = to / 2;
                    int y = to % 2;
                    if (dist[x][y] == -1) {
                        dist[x][y] = dist[p / 2][p % 2] + 1;
                        q[++r] = to;
                    }
                }
            }
        }
        return dist[e / 2][e % 2] != -1;
    }

    static void add_edge(int p1, int p2, int p3) {
        edges[++edgeCount] = new Edge(p2, head[p1], p3);
        head[p1] = edgeCount;
        edges[++edgeCount] = new Edge(p1, head[p2], 0);
        head[p2] = edgeCount;
    }

    static int dfs(int node, int flow) {
        int total_flow = 0;
        if (node == e) return flow;
        for (int i = head[node]; i != 0 && flow > 0; i = edges[i].prev) {
            if (edges[i].flow > 0 && dist[node / 2][node % 2] + 1 == dist[edges[i].to / 2][edges[i].to % 2]) {
                int a = dfs(edges[i].to, Math.min(edges[i].flow, flow));
                if (a > 0) {
                    edges[i].flow -= a;
                    edges[i ^ 1].flow += a;
                    flow -= a;
                    total_flow += a;
                }
            }
        }
        if (total_flow == 0) {
            dist[node / 2][node % 2] = INF;
        }
        return total_flow;
    }

    static int max_flow() {
        int total_flow = 0;
        while (bfs()) {
            int flow = dfs(s, INF);
            while (flow > 0) {
                total_flow += flow;
                flow = dfs(s, INF);
            }
        }
        return total_flow;
    }

    static void run_bfs() {
        for (int i = 0; i < dist.length; i++) {
            Arrays.fill(dist[i], 60);
        }
        dist[start_x][start_y] = 0;
        int l = 0, r = 0;
        Q[++r] = new Point(start_x, start_y);
        visited[start_x][start_y] = 1;
        while (l < r) {
            Point pnt = Q[++l];
            int ax = pnt.x, ay = pnt.y;
            for (int i = 0; i < 4; i++) {
                int nx = ax + move_x[i];
                int ny = ay + move_y[i];
                if (check_cell(nx, ny)) {
                    dist[nx][ny] = dist[ax][ay] + 1;
                    visited[nx][ny] = 1;
                    Q[++r] = new Point(nx, ny);
                }
            }
        }
    }

    static void find_paths(int tx, int ty, int idx) {
        int l = 0, r = 0;
        Q[++r] = new Point(tx, ty);
        for (int i = 0; i < visited.length; i++) {
            Arrays.fill(visited[i], 0);
        }
        for (int i = 0; i < Dis.length; i++) {
            Arrays.fill(Dis[i], 60);
        }
        visited[tx][ty] = 1;
        Dis[tx][ty] = 0;
        while (l < r) {
            Point pnt = Q[++l];
            int ax = pnt.x, ay = pnt.y;
            for (int i = 0; i < 4; i++) {
                int nx = ax + move_x[i];
                int ny = ay + move_y[i];
                if (check_cell(nx, ny)) {
                    Dis[nx][ny] = Dis[ax][ay] + 1;
                    if (Dis[nx][ny] < dist[nx][ny]) {
                        visited[nx][ny] = 1;
                        Q[++r] = new Point(nx, ny);
                    }
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (Dis[i][j] <= t && S[i][j] > '0' && S[i][j] <= '9' && Dis[i][j] <= dist[i][j]) {
                    add_edge(idx, id[i][j] + total, INF);
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());
        for (int i = 0; i < n; i++) {
            maze[i] = br.readLine().toCharArray();
        }
        for (int i = 0; i < n; i++) {
            S[i] = br.readLine().toCharArray();
        }
        outer:
        for (start_x = 0; start_x < n; start_x++) {
            for (start_y = 0; start_y < n; start_y++) {
                if (maze[start_x][start_y] == 'Z') break outer;
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                id[i][j] = ++total;
            }
        }
        s = 2 * total + 1;
        e = s + 1;
        Arrays.fill(head, 0);
        run_bfs();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (S[i][j] > '0' && S[i][j] <= '9') {
                    add_edge(s, id[i][j], S[i][j] - '0');
                    find_paths(i, j, id[i][j]);
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (S[i][j] > '0' && S[i][j] <= '9') {
                    add_edge(id[i][j] + total, e, S[i][j] - '0');
                }
            }
        }
        System.out.println(max_flow());
    }
}
